nextflow_process {

    name "Test Process GTDBTK_CLASSIFYWF"
    script "../main.nf"
    process "GTDBTK_CLASSIFYWF"
    config './nextflow.config'

    tag "modules"
    tag "modules_nfcore"
    tag "gtdbtk"
    tag "gtdbtk/classifywf"

    // Using special mini test-data provided to use via GTDB developers
    test("E. coli - genome fasta") {
        def gtdb_db
        setup {
            gtdb_db = extract('https://github.com/nf-core/test-datasets/raw/refs/heads/mag/databases/gtdbtk/gtdbtk_mockup_r232_20260507.tar.gz')
        }

        when {

            params {
                // Recommended by the GTDB developers: https://data.gtdb.ecogenomic.org/releases/latest/auxillary_files/gtdbtk_package/mockup_db/HOWTO.txt
                // The `--place_species` requires comparison against a full database and goes through the full classfywf pipeline
                module_args = '--extension fa --place_species'
            }

            process {
                """
                input[0] = [
                    [ id:'test', single_end:false, assembler:'SPADES' ],
                    [file(params.modules_testdata_base_path + 'genomics/prokaryotes/escherichia_coli/genome/genome.fa', checkIfExists: true)]
                ]
                input[1] = [ [ id:'mockup' ], file('${gtdb_db}') ]
                input[2] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out, unstableKeys: ["gtdb_outdir", "warnings", "failed", "log"])).match() }
            )
        }
    }

    test("sarscov2 - genome fasta - stub") {

        options "-stub"

        when {

            params {
                // Recommended by the GTDB developers: https://data.gtdb.ecogenomic.org/releases/latest/auxillary_files/gtdbtk_package/mockup_db/HOWTO.txt
                // The `--place_species` requires comparison against a full database and goes through the full classfywf pipeline
                module_args = '--extension fa --place_species'
            }

            process {
                """
                input[0] = [ [ id:'test', single_end:false, assembler:'SPADES' ], [] ]
                input[1] = [ [ id:'mockup' ], [] ]
                input[2] = false
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }
    }
}

